/**
 * Generates the night stylesheet for every converted application.
 *
 *   node tools/gen-dark-css.mjs [--check]
 *
 * For each apps/web/src/features/<app>/<app>.legacy.css it writes a sibling <app>.dark.css
 * holding only the declarations whose colour actually changes at night, at a higher
 * specificity, under :root[data-theme='dark'].
 *
 * Why a sibling file rather than a rewrite of the legacy stylesheet: those stylesheets were
 * generated by tools/scope-css.mjs from legacy/*.html, but 18 of the 21 have since been
 * hand-edited (fonts, page colours, deleted rules) without the HTML being updated, so the
 * HTML is no longer the source of truth and regenerating through it would revert real work.
 * Deriving the night sheet FROM the current CSS keeps this re-runnable no matter which of the
 * two is edited next.
 *
 * --check exits non-zero if any generated file is out of date, for CI.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { NIGHT, mapColor, mapVar } from './dark-palette.mjs'

const FEATURES = 'apps/web/src/features'
const check = process.argv.includes('--check')

/** Splits top-level rules, keeping @media/@keyframes blocks intact. */
function splitRules(css) {
  const rules = []
  let depth = 0
  let start = 0
  for (let i = 0; i < css.length; i++) {
    const c = css[i]
    if (c === '{') depth++
    else if (c === '}') {
      depth--
      if (depth === 0) {
        rules.push(css.slice(start, i + 1))
        start = i + 1
      }
    }
  }
  return rules.map((r) => r.trim()).filter(Boolean)
}

/** Declarations, with comments stripped and `;` inside url()/rgb() left alone. */
function splitDeclarations(body) {
  const out = []
  let depth = 0
  let current = ''
  for (const ch of body.replace(/\/\*[\s\S]*?\*\//g, '')) {
    if (ch === '(') depth++
    else if (ch === ')') depth--
    if (ch === ';' && depth === 0) {
      out.push(current)
      current = ''
    } else current += ch
  }
  out.push(current)
  return out.map((d) => d.trim()).filter(Boolean)
}

const COLOR_TOKEN = /#[0-9a-fA-F]{3,8}\b|rgba?\([^()]*\)/g

/** Rewrites every colour literal in one declaration; returns null when nothing changes. */
function mapDeclaration(prop, value, isScopeRoot) {
  if (prop.startsWith('--')) {
    const bare = value.replace(/\s*!important\s*$/, '')
    const mapped = mapVar(prop, bare)
    return mapped === null ? null : value.replace(bare, mapped)
  }
  let changed = false
  const next = value.replace(COLOR_TOKEN, (token) => {
    const mapped = mapColor(prop, token, { isScopeRoot })
    if (mapped === null) return token
    changed = true
    return mapped
  })
  return changed ? next : null
}

function prefix(prelude, scope) {
  return prelude
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => `:root[data-theme='dark'] ${s}`)
    .join(',\n')
}

function transform(css, scope, stats) {
  const out = []
  for (const rule of splitRules(css)) {
    const open = rule.indexOf('{')
    if (open < 0) continue
    const prelude = rule.slice(0, open).replace(/\/\*[\s\S]*?\*\//g, '').trim()
    const body = rule.slice(open + 1, rule.lastIndexOf('}'))
    if (!prelude) continue

    if (prelude.startsWith('@media')) {
      const inner = transform(body, scope, stats)
      if (inner.trim()) out.push(`${prelude} {\n${inner}\n}`)
      continue
    }
    // Keyframes cannot be overridden by specificity — the name would have to be redefined,
    // which would change the animation for day mode too. Counted and reported instead.
    if (prelude.startsWith('@keyframes')) {
      if (COLOR_TOKEN.test(body)) stats.skippedKeyframes.push(prelude.trim())
      COLOR_TOKEN.lastIndex = 0
      continue
    }
    if (prelude.startsWith('@')) continue

    const isScopeRoot = prelude
      .split(',')
      .map((s) => s.trim())
      .some((s) => s === scope)

    const kept = []
    for (const decl of splitDeclarations(body)) {
      const i = decl.indexOf(':')
      if (i < 0) continue
      const prop = decl.slice(0, i).trim()
      const value = decl.slice(i + 1).trim()
      const mapped = mapDeclaration(prop, value, isScopeRoot)
      if (mapped !== null) {
        kept.push(`  ${prop}: ${mapped};`)
        stats.mapped++
      }
    }
    if (kept.length) out.push(`${prefix(prelude, scope)} {\n${kept.join('\n')}\n}`)
  }
  return out.join('\n')
}

/** The scope class is recorded in the generated stylesheet's header comment. */
function scopeOf(css, file) {
  const m = /scoped under (\.[A-Za-z0-9_-]+)/.exec(css.slice(0, 400))
  if (!m) throw new Error(`cannot determine scope class from the header of ${file}`)
  return m[1]
}

const apps = readdirSync(FEATURES, { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => {
    const legacy = join(FEATURES, d.name, `${d.name}.legacy.css`)
    return existsSync(legacy) ? { name: d.name, legacy, dark: join(FEATURES, d.name, `${d.name}.dark.css`) } : null
  })
  .filter(Boolean)

let stale = 0
let totalMapped = 0
const allSkipped = []

for (const app of apps) {
  const css = readFileSync(app.legacy, 'utf8')
  const scope = scopeOf(css, app.legacy)
  const stats = { mapped: 0, skippedKeyframes: [] }
  const rules = transform(css, scope, stats)

  // Controls that never declared a background — .search, bare <input>, <select>, date pickers,
  // scrollbars — take the browser's own light chrome, and a codemod that rewrites declarations
  // has nothing to rewrite for them. So this pair is stated once per application rather than
  // derived: color-scheme repaints the native widgets, and because it leaves them the
  // browser's neutral grey, which fights the navy surfaces, the controls also get the card
  // colour. Both are emitted BEFORE the mapped rules and at low specificity, so any control
  // the application actually styled still wins. Checkboxes and radios are excluded — a
  // background would flatten the native tick that color-scheme has already darkened.
  const control = [`${scope} input:not([type='checkbox']):not([type='radio'])`, `${scope} select`, `${scope} textarea`]
    .map((s) => `:root[data-theme='dark'] ${s}`)
    .join(',\n')
  const baseline =
    `:root[data-theme='dark'] ${scope} {\n  color-scheme: dark;\n}\n` +
    `${control} {\n  background: ${NIGHT.surface};\n}\n`

  const header = `/* Night mode for ${app.name}, derived from ${app.name}.legacy.css.
 * Generated — do not hand-edit; re-run \`node tools/gen-dark-css.mjs\`.
 *
 * Only the declarations whose colour changes at night are here; everything else is inherited
 * from the light stylesheet. Brand and status colours are deliberately absent because they
 * keep their identity in both themes — see tools/dark-palette.mjs for the rules.
 */\n`
  const next = header + baseline + rules + '\n'
  const current = existsSync(app.dark) ? readFileSync(app.dark, 'utf8') : ''

  totalMapped += stats.mapped
  for (const k of stats.skippedKeyframes) allSkipped.push(`${app.name}: ${k}`)

  if (next === current) continue
  stale++
  if (check) {
    console.error(`stale: ${app.dark}`)
    continue
  }
  writeFileSync(app.dark, next)
  console.log(`${app.dark}: ${stats.mapped} declarations mapped under ${scope}`)
}

if (allSkipped.length) {
  console.log(`\nkeyframes with colours, left in their day form (${allSkipped.length}):`)
  for (const k of allSkipped) console.log(`  ${k}`)
}

if (check && stale) {
  console.error(`\n${stale} generated night stylesheet(s) out of date — run node tools/gen-dark-css.mjs`)
  process.exit(1)
}
if (!check) console.log(`\n${apps.length} applications, ${totalMapped} declarations mapped`)
